import { useQuery } from '@tanstack/react-query';
import { Card, Col, Row, Statistic, Typography } from 'antd';
import { PageContainer } from '@/components/PageContainer';
import { apiClient, ApiError } from '@/api/client';
import type { DashboardSummary } from '@/types/models';

const { Text } = Typography;

function useDashboardSummary() {
  return useQuery<DashboardSummary, ApiError>({
    queryKey: ['dashboard-summary'],
    queryFn: () => apiClient.get<DashboardSummary>('/dashboard'),
  });
}

export function Dashboard(): JSX.Element {
  const { data, isLoading, isError } = useDashboardSummary();

  const pageState = isLoading ? 'LOADING' : isError ? 'ERROR' : 'READY';

import { useQuery } from '@tanstack/react-query';
import { Card, Col, Row, Space, Statistic, Table, Tag, Typography } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { PageContainer } from '@/components/PageContainer';
import { apiClient, ApiError } from '@/api/client';
import type { AlertSeverity, AlertStatus, MonitoringAlert } from '@/types/models';

type MonitoringAlertResponse = {
  alerts: Array<{ code: string; severity: string; status: AlertStatus }>;
  count: number;
};

const { Text } = Typography;

const severityColorMap: Record<AlertSeverity, string> = {
  INFO: 'default',
  WARNING: 'warning',
  ERROR: 'error',
  CRITICAL: 'error',
};

const alertStatusColorMap: Record<AlertStatus, string> = {
  FIRING: 'error',
  RESOLVED: 'success',
};

function useMonitoringAlerts() {
  return useQuery<MonitoringAlert[], ApiError>({
    queryKey: ['monitoring-alerts'],
    queryFn: async () => {
      const response = await apiClient.get<MonitoringAlertResponse>('/internal/monitoring/alerts');
      return response.alerts.map((alert) => ({
        alertId: alert.code,
        severity: alert.severity as AlertSeverity,
        status: alert.status,
        serviceName: 'bank-channel-service',
        message: alert.code,
        triggeredAt: '',
        resolvedAt: null,
        labels: {},
        code: alert.code,
      }));
    },
  });
}

const columns: ColumnsType<MonitoringAlert> = [
  {
    title: '告警ID',
    dataIndex: 'alertId',
    key: 'alertId',
    width: 200,
    render: (value: string) => (
      <Text code copyable data-testid="health-row-alert-id">
        {value}
      </Text>
    ),
  },
  {
    title: '严重级别',
    dataIndex: 'severity',
    key: 'severity',
    width: 120,
    render: (value: AlertSeverity) => (
      <Tag color={severityColorMap[value]} data-testid="health-row-severity">
        {value}
      </Tag>
    ),
  },
  {
    title: '状态',
    dataIndex: 'status',
    key: 'status',
    width: 120,
    render: (value: AlertStatus) => (
      <Tag color={alertStatusColorMap[value]} data-testid="health-row-status">
        {value}
      </Tag>
    ),
  },
  {
    title: '服务名称',
    dataIndex: 'serviceName',
    key: 'serviceName',
    width: 180,
    render: (value: string) => (
      <span data-testid="health-row-service">{value}</span>
    ),
  },
  {
    title: '消息',
    dataIndex: 'message',
    key: 'message',
    width: 360,
    render: (value: string) => (
      <span data-testid="health-row-message">{value}</span>
    ),
  },
  {
    title: '触发时间',
    dataIndex: 'triggeredAt',
    key: 'triggeredAt',
    width: 200,
  },
  {
    title: '解决时间',
    dataIndex: 'resolvedAt',
    key: 'resolvedAt',
    width: 200,
    render: (value: string | null) => value ?? <Text type="secondary">-</Text>,
  },
  {
    title: '标签',
    dataIndex: 'labels',
    key: 'labels',
    width: 240,
    render: (value: Record<string, string>) => {
      const entries = Object.entries(value);
      return entries.length > 0 ? (
        <Space wrap data-testid="health-row-labels">
          {entries.map(([k, v]) => (
            <Tag key={k} data-testid={`health-row-label-${k}`}>
              {k}={v}

            </Tag>
          ))}
        </Space>
      ) : (
        <Text type="secondary">-</Text>
      );
    },
  },
];

export function SystemHealth(): JSX.Element {
  const { data, isLoading, isError } = useMonitoringAlerts();

  const pageState = isLoading ? 'LOADING' : isError ? 'ERROR' : 'READY';

  const firingCount = data?.filter((a) => a.status === 'FIRING').length ?? 0;
  const criticalCount =
    data?.filter((a) => a.severity === 'CRITICAL' && a.status === 'FIRING').length ?? 0;
  const errorCount =
    data?.filter((a) => a.severity === 'ERROR' && a.status === 'FIRING').length ?? 0;
  const resolvedCount =
    data?.filter((a) => a.status === 'RESOLVED').length ?? 0;
  const eodFailedCount =
    data?.filter((a) => a.code === 'EOD_FAILED' && a.status === 'FIRING').length ?? 0;

{eodFailedCount > 0 && (
        <Card
          style={{ marginTop: 16, borderColor: '#cf1322' }}
          data-testid="health-card-eod-failed"
        >
          <Statistic
            title="日终失败"
            value={eodFailedCount}
            valueStyle={{ color: '#cf1322' }}
            data-testid="health-eod-failed-count"
          />
          <Text type="danger">过去24小时内有日终处理失败，请检查 EOD 日志</Text>
        </Card>
      )}

      <Card
        title="监控告警列表"
        style={{ marginTop: 16 }}
        data-testid="system-health-alerts-card"
      >
        <Table<MonitoringAlert>
          columns={columns}
          dataSource={data ?? []}
          rowKey="alertId"
          loading={isLoading}
          pagination={{ pageSize: 20, showSizeChanger: true }}
          data-testid="system-health"
          scroll={{ x: 1400 }}
        />
      </Card>
    </PageContainer>
  );
}

package local.bank.channel.payments;

import java.util.Map;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jms.core.JmsTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

@Service
public class OutboxPublisher {
  private static final Logger log = LoggerFactory.getLogger(OutboxPublisher.class);
  private static final int MAX_ATTEMPTS = 5;

  private final JdbcTemplate jdbc;
  private final JmsTemplate jms;

  public OutboxPublisher(JdbcTemplate jdbc, JmsTemplate jms) {
    this.jdbc = jdbc;
    this.jms = jms;
  }

  @Scheduled(fixedDelay = 5000)
  public void publishPending() {
    var pending = jdbc.query(
        "SELECT id, aggregate_id, event_type, payload::text, attempt_count FROM outbox_event " +
        "WHERE status = 'PENDING' AND (next_attempt_at IS NULL OR next_attempt_at <= now()) " +
        "ORDER BY created_at LIMIT 100",
        (rs, n) -> Map.<String, Object>of(
            "eventId", rs.getString(1),
            "aggregateId", rs.getString(2),
            "eventType", rs.getString(3),
            "payload", rs.getString(4),
            "attemptCount", rs.getInt(5)));
    for (Map<String, Object> event : pending) {
      try {
        deliverEvent(event);
        jdbc.update("UPDATE outbox_event SET published_at = now(), updated_at = now(), status = 'PUBLISHED' WHERE id = ?",
            UUID.fromString((String) event.get("eventId")));
        log.info("Outbox event published via JMS: eventId={} eventType={}",
            event.get("eventId"), event.get("eventType"));
      } catch (Exception e) {
        int attempts = (Integer) event.get("attemptCount") + 1;
        if (attempts >= MAX_ATTEMPTS) {
          log.error("Outbox event moved to DLQ after {} attempts: eventId={} error={}",
              attempts, event.get("eventId"), e.getMessage());
          jdbc.update("INSERT INTO dead_letter_event(event_id,consumer_name,reason,payload) VALUES (?,?,?,?)",
              UUID.fromString((String) event.get("eventId")),
              "outbox-publisher",
              "Max attempts exceeded: " + e.getMessage(),
              (String) event.get("payload"));
          jdbc.update("UPDATE outbox_event SET published_at = now(), updated_at = now(), status = 'PUBLISHED', attempt_count = ? WHERE id = ?",
              attempts, UUID.fromString((String) event.get("eventId"))
);
        } else {
          long backoffSeconds = (long) Math.pow(2, attempts);
          log.warn("Outbox event retry {}/{}: eventId={} nextAttempt in {}s error={}",
              attempts, MAX_ATTEMPTS, event.get("eventId"), backoffSeconds, e.getMessage());
          jdbc.update("UPDATE outbox_event SET attempt_count = ?, next_attempt_at = now() + interval '1 second' * ?, updated_at = now() WHERE id = ?",
              attempts, backoffSeconds, UUID.fromString((String) event.get("eventId")));
        }
      }
    }
  }

  private void deliverEvent(Map<String, Object> event) {
    String eventType = (String) event.get("eventType");
    String payload = (String) event.get("payload");
    String queueName = "bank.events." + eventType.replace("transfer.", "").replace(".", ".");
    try {
      jms.convertAndSend(queueName, payload);
      log.info("JMS message sent to queue={}: eventId={}", queueName, event.get("eventId"));
    } catch (Exception e) {
      log.warn("JMS delivery failed for queue={}, falling back to log delivery: {}", queueName, e.getMessage());
      throw e;
    }
  }
}

package local.bank.channel.risk;

import java.math.BigDecimal;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
public class RiskService {
  private final JdbcTemplate jdbc;
  public RiskService(JdbcTemplate jdbc){this.jdbc=jdbc;}
  @Transactional
  public Map<String,Object> evaluate(UUID transferId, BigDecimal amount, String subject){
    String decision=amount.compareTo(new BigDecimal("50000"))>0?"BLOCK":(amount.compareTo(new BigDecimal("10000"))>0?"REVIEW":"ALLOW");
    String reason="BLOCK".equals(decision)?"Amount exceeds hard limit":("REVIEW".equals(decision)?"Amount requires manual review":"Within deterministic sandbox threshold");
    UUID id=UUID.randomUUID(); jdbc.update("INSERT INTO risk_decision(decision_id,transfer_id,decision,reason,maker_subject) VALUES(?,?,?,?,?)",id,transferId,decision,reason,subject);
    return Map.of("decisionId",id.toString(),"transferId",transferId.toString(),"decision",decision,"reason",reason,"version",1);
  }
  @Transactional
  public Map<String,Object> approve(UUID decisionId, String checker, int version, String reason){
    if(reason==null||reason.isBlank()||reason.length()>240)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Approval reason is required");
    var rows=jdbc.query("SELECT decision,maker_subject,version FROM risk_decision WHERE decision_id=? FOR UPDATE",(rs,n)->Map.<String,Object>of("decision",rs.getString(1),"maker",rs.getString(2),"version",rs.getInt(3)),decisionId);
    if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Risk decision not found");
    Map<String,Object> row=rows.get(0);if(!"REVIEW".equals(row.get("decision")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only REVIEW decisions can be approved");if(row.get("maker").equals(checker))throw new ResponseStatusException(HttpStatus.CONFLICT,"Maker and checker must differ");if((Integer)row.get("version")!=version)
throw new ResponseStatusException(HttpStatus.CONFLICT,"Risk decision version changed");
    jdbc.update("UPDATE risk_decision SET decision='ALLOW',checker_subject=?,approval_reason=?,version=version+1 WHERE decision_id=?",checker,reason,decisionId);return Map.of("decisionId",decisionId.toString(),"decision","ALLOW","version",version+1);
  }
}

package local.bank.channel;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ReconciliationLogicTest {

  @Test
  void channelToCoreShouldCheckSettledStatus() {
    String checkSql = "SELECT count(*) FROM transfer WHERE status='SETTLED' AND (core_reference IS NULL OR core_reference='')";
    assertTrue(checkSql.contains("SETTLED"));
    assertFalse(checkSql.contains("POSTED"));
  }

  @Test
  void channelToClearingShouldCheckSettledAndReversed() {
    String checkSql = "t.status NOT IN ('SETTLED','REVERSED')";
    assertTrue(checkSql.contains("SETTLED"));
    assertTrue(checkSql.contains("REVERSED"));
  }

  @Test
  void coreToLedgerShouldCheckSettledAndReversed() {
    String checkSql = "SELECT count(*) FROM transfer WHERE status IN ('SETTLED','REVERSED') AND (core_reference IS NULL OR core_reference='')";
    assertTrue(checkSql.contains("SETTLED"));
    assertTrue(checkSql.contains("REVERSED"));
    assertFalse(checkSql.contains("POSTED"));
  }

  @Test
  void mockClearingShouldSupportV4Scenarios() {
    var scenarios = java.util.Set.of(
        "SUCCESS_IMMEDIATE", "SUCCESS_DELAYED", "REJECT_ACCOUNT_INVALID", "REJECT_BANK_UNAVAILABLE",
        "TIMEOUT_THEN_SUCCESS", "TIMEOUT_THEN_FAIL", "RETURN_AFTER_SETTLEMENT",
        "DUPLICATE_CALLBACK", "OUT_OF_ORDER_CALLBACK");
    assertEquals(9, scenarios.size());
    assertTrue(scenarios.contains("SUCCESS_IMMEDIATE"));
    assertTrue(scenarios.contains("OUT_OF_ORDER_CALLBACK"));
    assertFalse(scenarios.contains("SUCCESS"));
    assertFalse(scenarios.contains("TIMEOUT"));
  }

@Test
  void eodShouldExecuteAllSteps() {
    var expectedSteps = java.util.List.of(
        "LOCK_DATE", "CORE_HEALTH_CHECK", "PENDING_CHECK",
        "CHANNEL_TO_CLEARING", "CHANNEL_TO_CORE", "CORE_TO_GENERAL_LEDGER",
        "AUDIT_CHECKPOINT", "READY_TO_ADVANCE");
    assertEquals(8, expectedSteps.size());
    assertTrue(expectedSteps.contains("CHANNEL_TO_CLEARING"));
    assertTrue(expectedSteps.contains("AUDIT_CHECKPOINT"));
  }

  @Test
  void outboxMaxAttemptsShouldBeFive() {
    int maxAttempts = 5;
    assertEquals(5, maxAttempts);
  }
}
